{"content":"import unittest

from forth import StackUnderflowError, evaluate


class ForthTest(unittest.TestCase):
    def test_numbers_and_arithmetic(self):
        cases = [
            ('', []),
            ('1 2 3', [1, 2, 3]),
            ('1 2 +', [3]),
            ('3 5 -', [-2]),
            ('3 4 *', [12]),
            ('8 3 /', [2]),
            ('0 8 - 3 /', [-2]),
            ('8 0 3 - /', [-2]),
            ('0 8 - 0 3 - /', [2]),
            ('1 2 + 4 * 3 -', [9]),
        ]
        for source, expected in cases:
            with self.subTest(source=source):
                self.assertEqual(evaluate([source]), expected)

    def test_large_integer_division_is_exact(self):
        value = 10 ** 100 + 2
        self.assertEqual(evaluate([f'{value} 3 /']), [value // 3])

    def test_stack_operations(self):
        cases = [
            ('1 DUP', [1, 1]),
            ('1 2 drop', [1]),
            ('1 2 SwAp', [2, 1]),
            ('1 2 oVeR', [1, 2, 1]),
        ]
        for source, expected in cases:
            with self.subTest(source=source):
                self.assertEqual(evaluate([source]), expected)

    def test_all_stack_underflows_have_messages(self):
        for word in ('+', '-', '*', '/', 'dup', 'drop', 'swap', 'over'):
            sources = [word]
            if word not in ('dup', 'drop'):
                sources.append(f'1 {word}')
            for source in sources:
                with self.subTest(source=source):
                    with self.assertRaisesRegex(StackUnderflowError, 'Insufficient'):
                        evaluate([source])

    def test_division_by_zero(self):
        with self.assertRaisesRegex(ZeroDivisionError, 'divide by zero'):
            evaluate(['1 0 /'])

    def test_definitions_and_case_insensitivity(self):
        self.assertEqual(
            evaluate([': Square DuP * ;', ': FOUR 2 square ;', 'four SQUARE']),
            [16],
        )

    def test_definition_spans_lines_and_can_be_empty(self):
        self.assertEqual(evaluate([': foo', '1 2 +', '; : noop ; foo noop']), [3])

    def test_redefinition_preserves_previous_bindings(self):
        self.assertEqual(
            evaluate([': foo 5 ; : bar foo ; : foo 6 ; bar foo']), [5, 6]
        )
        self.assertEqual(evaluate([': foo 5 ; : foo foo 1 + ; foo']), [6])
        self.assertEqual(
            evaluate([': add + ; : + * ; 2 3 add 2 3 +']), [5, 6]
        )

    def test_builtin_words_can_be_redefined(self):
        self.assertEqual(evaluate([': DUP 7 ; 1 dup']), [1, 7])

    def test_non_numeric_names(self):
        for name in ('word1', '1word', '!!', '-1', '١'):
            with self.subTest(name=name):
                self.assertEqual(evaluate([f': {name} 42 ; {name}']), [42])

    def test_invalid_source_has_meaningful_errors(self):
        for source in (
            'unknown', ': foo unknown ;', ': 123 1 ;', ':', ': ;',
            ': : 1 ;', ': foo 1', ': foo : bar 1 ; ;', ';', ': foo foo ;',
        ):
            with self.subTest(source=source):
                with self.assertRaisesRegex(ValueError, '.+'):
                    evaluate([source])

    def test_calls_do_not_share_state(self):
        self.assertEqual(evaluate([': foo 1 ; foo']), [1])
        self.assertEqual(evaluate([]), [])
        with self.assertRaisesRegex(ValueError, 'undefined operation'):
            evaluate(['foo'])


if __name__ == '__main__':
    unittest.main()
